-- ============================================================
-- Campus Bulkmart — Phase 2c Migration (2/2)
-- Delivery origin + Ikeja geofence boundary, stored as settings
-- entries (same key/value pattern as appConfig/siteContent).
-- Both are admin-editable in Phase 2d.
--
-- Run in Supabase Dashboard → SQL Editor, AFTER add-landmarks-table.sql.
-- ============================================================

-- ── Origin ──
-- The point every delivery distance is measured from. Editable in
-- Phase 2d's admin panel — landmark distances recalculate live via
-- Haversine, so this can change without touching any other data.
insert into public.settings (key, value)
values (
  'deliveryOrigin',
  '{
    "address": "1-5 Oba Akinjobi Way, Ikeja GRA, Ikeja 101233, Lagos",
    "lat": 6.590565114838804,
    "lng": 3.342276195963966
  }'::jsonb
)
on conflict (key) do update set value = excluded.value, updated_at = now();

